SELECT * FROM (
select
id, account_id, account_type, purse_type, alter_type, amount, join_record_id, remark,
create_time
from account_purse_alter_record

    and account_type = #{query.accountType}

        and account_id = #{query.accountId}


        and purse_type = #{query.purseType}


        and alter_type in

            #{item}



        and `id` in

            #{item}



        and create_time >= #{query.createStartTime}


        and create_time < #{query.createEndTime}


union all
select
id, account_id, account_type, purse_type, 2 as alter_type, apply_amount as amount,
tripartite_trade_no as join_record_id, -1 as remark,
apply_time as create_time
from account_purse_roll_out

    audit_state = 0
    and account_type = #{query.accountType}

        and account_id = #{query.accountId}


        and purse_type = #{query.purseType}


        and `id` in

            #{item}



        and apply_time >= #{query.createStartTime}


        and apply_time < #{query.createEndTime}


) as t
ORDER BY create_time DESC
